{
  "id": "V009",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 번역문을 만들고 검토하려는 목적이 보존됩니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "번역, 누락 여부 확인, 원문과 비교 검토가 모두 포함됩니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "한국어 기업 소식 기사와 영어 번역문이 포함됩니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "한국어 기사 내용이 입력으로 보존됩니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "영어 번역문이 결과물로 보존됩니다."
    },
    {
      "field": "constraints",
      "score": 0,
      "reason": "원문에 없는 인용이나 성과를 추가하지 않는 제약이 모든 뷰에서 빠졌습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "뷰에 원문에 없는 기능을 추가했다는 근거가 없습니다."
    },
    {
      "field": "roles",
      "score": 1,
      "reason": "편집자의 검토 역할은 보존되지만, 게시 결정이 편집자에게 있다는 내용은 없습니다."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "원문에 없는 인용이나 성과를 추가하지 않으며",
      "view_quote": "",
      "reason": "번역에서 원문에 없는 내용을 추가하지 않는 제약이 세 뷰 모두에 없습니다."
    },
    {
      "type": "OMISSION",
      "source_quote": "게시 결정은 편집자가 합니다.",
      "view_quote": "",
      "reason": "게시 결정 권한이 편집자에게 있다는 내용이 세 뷰 모두에 없습니다."
    }
  ],
  "permission_interpretation": "편집자가 번역문을 검토하고 게시를 결정한다는 원문은 AI가 게시하거나 승인한다는 뜻이 아닙니다."
}
